from datetime import datetime, time


class Notifier:
    CHANNELS = ("email", "sms", "push")

    def __init__(
        self,
        quiet_start: time = time(22, 0),
        quiet_end: time = time(7, 0),
    ) -> None:
        self.quiet_start = quiet_start
        self.quiet_end = quiet_end
        self.users_data: dict[str, dict[str, bool]] = {}

    def users(self) -> list[str]:
        return sorted(self.users_data.keys())

    def add_user(self, user: str) -> None:
        self.users_data[user] = {
            "email": True,
            "sms": False,
            "push": False,
        }

    def set_channel(self, user: str, channel: str, enabled: bool) -> None:
        if channel not in self.CHANNELS:
            raise ValueError(f"Invalid channel '{channel}'. Must be one of {self.CHANNELS}.")
        if user not in self.users_data:
            self.add_user(user)
        self.users_data[user][channel] = enabled

    def enabled_channels(self, user: str) -> list[str]:
        """Return the channels the user has enabled, in CHANNELS order."""
        if user not in self.users_data:
            self.add_user(user)
        user_preferences = self.users_data[user]
        return [channel for channel in self.CHANNELS if user_preferences.get(channel, False)]

    def _is_quiet_hour(self, current_time: time) -> bool:
        if self.quiet_start == self.quiet_end:
            return False
        if self.quiet_start < self.quiet_end:
            return self.quiet_start <= current_time < self.quiet_end
        # Spans midnight (e.g., 22:00 to 07:00)
        return current_time >= self.quiet_start or current_time < self.quiet_end

    def send(self, user: str, message: str, at: datetime) -> list[str]:
        """Send a message; returns the channels it was delivered to, in CHANNELS order."""
        if user not in self.users_data:
            self.add_user(user)

        user_preferences = self.users_data[user]
        is_quiet = self._is_quiet_hour(at.time())
        delivered_channels: list[str] = []

        for channel in self.CHANNELS:
            if not user_preferences.get(channel, False):
                continue
            # During quiet hours, only email is delivered; sms and push are muted.
            if is_quiet and channel != "email":
                continue
            delivered_channels.append(channel)

        return delivered_channels
